{"point":{"id":"static_analysis","title":"Static Architecture Analysis","rationale":"A separate CLI-driven pipeline extracts declarations, lexical references, calls, resource ownership, framework relationships, and dataflow from TypeScript. It derives partitions, metrics, components, and findings with source provenance. IncrementalAnalyzer owns reusable component fragments and broadens invalidation for uncertain global effects. This is a substantial independent subsystem, not an established browser generation stage.","sourcePaths":["application/core/static-analysis/ports.ts","infrastructure/core/static-analysis/analyzer.ts","infrastructure/core/static-analysis/incremental.ts","infrastructure/core/static-analysis/context.ts","domain/core/static-analysis/schema.ts","domain/core/static-analysis/derive.ts","domain/core/static-analysis/persistence.ts","scripts/analysis/analyze.ts"],"relationships":[{"pointId":"composition","label":"shares source-layer classification with architecture boundary tests","kind":"related"}]},"sources":[{"path":"application/core/static-analysis/ports.ts","text":"import type { AnalysisArtifact, AnalysisView } from '../../../domain/core/static-analysis/schema';

/** A selection limits fact emission; imports may still be read for symbol resolution. */
export interface StaticAnalysisRequest {
  repositoryRoot: string;
  repositoryId: string;
  tsconfigPath: string;
  includePaths: readonly string[];
  views: readonly AnalysisView[];
  frameworks: readonly ('react' | 'zustand' | 'tldraw' | 'controller')[];
  metrics: { partitions: readonly ('directory' | 'layer' | 'single-group')[]; shuffleSeed: number; shuffleSamples: number };
}

/** Wall time, RSS and timestamps are deliberately outside deterministic persisted facts. */
export interface StaticAnalysisResult {
  artifact: AnalysisArtifact;
  measurements: { elapsedMs: number; peakRssBytes: number; phasesMs?: Record<string, number> };
  /** Compiler mode used to reconstruct an identical snapshot during incremental assembly. */
  execution?: { semanticResolution: boolean };
}
export interface StaticAnalyzer {
  analyze(request: StaticAnalysisRequest): Promise<StaticAnalysisResult>;
}
"},{"path":"infrastructure/core/static-analysis/analyzer.ts","text":"import type { StaticAnalyzer } from '../../../application/core/static-analysis/ports';
import { AnalysisContext, sha } from './context';
import { Declarations } from './declarations';
import { deriveAnalysis } from '../../../domain/core/static-analysis/derive';
import { extractLexical } from './lexical';
import { Resources } from './resources';
import { extractCalls } from './calls';
import { extractFrameworks } from './frameworks';
import { extractDataflow } from './dataflow';
import { connectCallbackCandidates } from './callbacks';

export const staticAnalyzer: StaticAnalyzer = {
  async analyze(request) {
    const started = performance.now();
    const phasesMs: Record<string, number> = {}; let previous = started;
    const phase = (name: string) => { const now = performance.now(); phasesMs[name] = now - previous; previous = now; if (process.env.STATIC_ANALYSIS_PROFILE) console.error(JSON.stringify({ phase: name, elapsedMs: phasesMs[name], rss: process.memoryUsage().rss, heap: process.memoryUsage().heapUsed })); };
    const context = new AnalysisContext(request), declarations = new Declarations(context);
    phase('parse');
    declarations.index(); declarations.imports(); declarations.composition();
    phase('containment');
    const references = request.views.some(view => view !== 'containment') ? extractLexical(context, declarations) : [];
    phase('lexical');
    if (request.views.some(view => ['calls', 'ownership', 'dependencies'].includes(view))) {
      const resources = new Resources(context, declarations); resources.initialize();
      phase('resources');
      const sites = extractCalls(context, declarations); phase('calls');
      extractFrameworks(context, declarations, resources, sites); phase('frameworks');
      if (request.views.some(view => ['ownership', 'dependencies'].includes(view))) {
        declarations.prepareDataflow(); phase('flow-symbols');
        context.releaseCompiler();
        extractDataflow(context, declarations, resources, references, sites);
        connectCallbackCandidates(context, declarations, sites);
      }
      phase('dataflow');
    }
    const artifact = context.finish();
    phase('snapshot');
    context.release(); references.length = 0;
    declarations.declarationOwners.clear(); declarations.receivers.clear(); declarations.scopeBindings.clear();
    declarations.parameterFields.clear();
    deriveAnalysis(artifact, request.metrics, sha);
    phase('derive');
    return { artifact, execution: { semanticResolution: context.usedSemanticResolution }, measurements: { elapsedMs: performance.now() - started, peakRssBytes: process.resourceUsage().maxRSS * 1024, phasesMs } };
  },
};
"},{"path":"infrastructure/core/static-analysis/incremental.ts","text":"import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import ts from 'typescript';
import type { StaticAnalysisRequest, StaticAnalysisResult, StaticAnalyzer } from '../../../application/core/static-analysis/ports';
import type { AnalysisArtifact } from '../../../domain/core/static-analysis/schema';
import { analysisDependencyEdges, dependencyComponents, mergeAnalysisFacts } from '../../../domain/core/static-analysis/incremental';
import { deriveAnalysis } from '../../../domain/core/static-analysis/derive';
import { validateAnalysisArtifact } from '../../../domain/core/static-analysis/persistence';
import { ANALYZER_VERSION, AnalysisContext, sha } from './context';
import { staticAnalyzer } from './analyzer';

export interface IncrementalCheckpoint {
  version: 1;
  fragments: { key: string; paths: string[]; artifact: AnalysisArtifact; semanticResolution: boolean }[];
}
export interface IncrementalResult extends StaticAnalysisResult {
  update: { changedFiles: string[]; analyzedFiles: string[]; reusedFiles: string[]; removedFiles: string[];
    components: number; fallbackReasons: string[]; derivedRecomputed: true };
}

/** Read current resolution, including previously missing imports, before trusting cached edges. */
function inventory(request: StaticAnalysisRequest) {
  const root = path.resolve(request.repositoryRoot), absoluteConfig = path.resolve(root, request.tsconfigPath);
  const config = ts.readConfigFile(absoluteConfig, ts.sys.readFile);
  if (config.error) throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, '\n'));
  const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, path.dirname(absoluteConfig));
  if (parsed.errors.length) throw new Error(parsed.errors.map(error => ts.flattenDiagnosticMessageText(error.messageText, '\n')).join('\n'));
  const selected = [...new Set(request.includePaths.map(file => path.relative(root, path.resolve(root, file)).replaceAll(path.sep, '/')))].sort();
  if (selected.some(file => file.startsWith('../') || path.isAbsolute(file))) throw new Error('Analysis input escapes repository');
  const host = ts.createCompilerHost(parsed.options, true);
  host.getCurrentDirectory = () => root;
  const program = ts.createProgram([...selected.map(file => path.resolve(root, file)), ...parsed.fileNames.filter(file => file.endsWith('.d.ts'))], parsed.options, host);
  const local = new Map<string, string>(), environment = new Map<string, string>(), edges: [string, string][] = [];
  const resolutions = new Map<string, string[]>(), fallback = new Set<string>();
  const relative = (file: string) => path.relative(root, file).replaceAll(path.sep, '/');
  const inside = (file: string) => !file.startsWith('../') && !path.isAbsolute(file) && !file.split('/').includes('node_modules');
  for (const source of program.getSourceFiles()) {
    const file = relative(source.fileName), content = readFileSync(source.fileName, 'utf8');
    if (!inside(file) || source.isDeclarationFile) {
      environment.set(inside(file) ? file : `external:${source.fileName}`, sha(content));
      if (selected.includes(file)) { local.set(file, sha(content)); fallback.add('selected-declaration-file'); }
      // Ambient declarations can expose types imported from ordinary local code
      // to every component, without an import in the consuming source file.
      for (const imported of ts.preProcessFile(content, true, true).importedFiles) {
        const target = ts.resolveModuleName(imported.fileName, source.fileName, parsed.options, host).resolvedModule?.resolvedFileName;
        if (target && inside(relative(target)) && !target.endsWith('.d.ts')) fallback.add('declaration-source-dependency');
      }
      for (const reference of source.referencedFiles) {
        const target = path.resolve(path.dirname(source.fileName), reference.fileName);
        if (inside(relative(target)) && !target.endsWith('.d.ts')) fallback.add('declaration-source-dependency');
      }
      continue;
    }
    local.set(file, sha(content));
    if (!ts.isExternalModule(source)) fallback.add('global-script');
    const inspect = (node: ts.Node) => {
      if (ts.isModuleDeclaration(node) && (ts.isStringLiteral(node.name) || node.flags & ts.NodeFlags.GlobalAugmentation)) fallback.add('module-or-global-augmentation');
      if (ts.isCallExpression(node) && (node.expression.kind === ts.SyntaxKind.ImportKeyword || ts.isIdentifier(node.expression) && node.expression.text === 'require')
        && (!node.arguments[0] || !ts.isStringLiteralLike(node.arguments[0]))) fallback.add('dynamic-module-resolution');
      ts.forEachChild(node, inspect);
    };
    inspect(source);
    const observations: string[] = [];
    for (const imported of ts.preProcessFile(content, true, true).importedFiles) {
      const target = ts.resolveModuleName(imported.fileName, source.fileName, parsed.options, host).resolvedModule?.resolvedFileName;
      observations.push(JSON.stringify([imported.fileName, target ? relative(target) : null]));
      if (target && inside(relative(target))) edges.push([file, relative(target)]);
    }
    resolutions.set(file, observations.sort());
    // Package boundaries can change resolution and containment without a TS edit.
    for (let directory = path.dirname(source.fileName); directory === root || directory.startsWith(root + path.sep); directory = path.dirname(directory)) {
      const manifest = path.join(directory, 'package.json');
      if (existsSync(manifest)) environment.set(relative(manifest), sha(readFileSync(manifest, 'utf8')));
      if (directory === root) break;
    }
  }
  for (const file of [request.tsconfigPath, 'package.json', 'package-lock.json']) if (existsSync(path.join(root, file))) environment.set(file, sha(readFileSync(path.join(root, file), 'utf8')));
  for (const file of selected) if (!local.has(file)) throw new Error(`Missing selected source file: ${file}`);
  if ([ts.ModuleResolutionKind.Node16, ts.ModuleResolutionKind.NodeNext].includes(parsed.options.moduleResolution!)) fallback.add('mode-sensitive-module-resolution');
  const environmentKey = sha(JSON.stringify({ version: `incremental-v1/analyzer-${ANALYZER_VERSION}`, compiler: ts.version, repositoryId: request.repositoryId,
    views: request.views, frameworks: request.frameworks, options: parsed.options, environment: [...environment].sort(([a], [b]) => a < b ? -1 : 1) }));
  return { selected, local, resolutions, edges, environmentKey, fallback: [...fallback].sort() };
}

/** Session-owned component cache. Unknown global effects deliberately broaden invalidation. */
export class IncrementalAnalyzer {
  private checkpoint: IncrementalCheckpoint = { version: 1, fragments: [] };
  private busy = false;
  constructor(private readonly extractor: StaticAnalyzer = staticAnalyzer) {}
  exportCheckpoint(): IncrementalCheckpoint { return structuredClone(this.checkpoint); }
  restoreCheckpoint(checkpoint: IncrementalCheckpoint) {
    if (this.busy) throw new Error('Cannot restore a running analysis');
    if (checkpoint.version !== 1) throw new Error('Unsupported incremental checkpoint version');
    const keys = new Set<string>();
    for (const fragment of checkpoint.fragments) {
      if (!/^[a-f0-9]{64}$/.test(fragment.key) || keys.has(fragment.key) || typeof fragment.semanticResolution !== 'boolean') throw new Error('Invalid incremental fragment');
      keys.add(fragment.key); validateAnalysisArtifact(fragment.artifact);
      if (JSON.stringify([...fragment.paths].sort()) !== JSON.stringify([...fragment.artifact.snapshot.scope.roots].sort())) throw new Error('Fragment scope differs from its artifact');
    }
    this.checkpoint = structuredClone(checkpoint);
  }
  async analyze(request: StaticAnalysisRequest): Promise<IncrementalResult> {
    if (this.busy) throw new Error('An incremental session cannot run concurrent updates');
    this.busy = true;
    try { return await this.update(request); } finally { this.busy = false; }
  }
  private async update(request: StaticAnalysisRequest): Promise<IncrementalResult> {
    const started = performance.now(), current = inventory(request);
    const selected = new Set(current.selected), previousFiles = new Map<string, string>();
    const graphEdges = [...current.edges];
    for (const entry of this.checkpoint.fragments) {
      for (const file of entry.artifact.snapshot.files) if (file.role === 'analyzed') previousFiles.set(file.path, file.contentHash);
      for (const edge of analysisDependencyEdges(entry.artifact)) if (current.local.has(edge[0]) && current.local.has(edge[1])) graphEdges.push(edge);
    }
    const groups = current.fallback.length ? [[...current.local.keys()].sort()] : dependencyComponents([...current.local.keys()], graphEdges);
    const previous = new Map(this.checkpoint.fragments.map(fragment => [fragment.key, fragment]));
    const next: IncrementalCheckpoint = { version: 1, fragments: [] }, analyzedFiles: string[] = [], reusedFiles: string[] = [];
    for (const members of groups) {
      const paths = members.filter(file => selected.has(file)); if (!paths.length) continue;
      const key = sha(JSON.stringify([current.environmentKey, paths, members.map(file => [file, current.local.get(file), current.resolutions.get(file)])]));
      const cached = previous.get(key);
      if (cached) { next.fragments.push(cached); reusedFiles.push(...paths); }
      else {
        const result = await this.extractor.analyze({ ...request, includePaths: paths });
        next.fragments.push({ key, paths, artifact: result.artifact, semanticResolution: result.execution?.semanticResolution ?? true });
        analyzedFiles.push(...paths);
      }
    }
    if (!next.fragments.length) throw new Error('Select at least one source file');
    // Fresh header pins the current commit/configuration/input set even on a cache hit.
    const context = new AnalysisContext(request);
    if (next.fragments.some(fragment => fragment.semanticResolution)) void context.checker;
    // Module extraction also discovers nested package manifests. They must remain
    // pinned even though assembly does not walk declarations again.
    const configurationPaths = new Set(context.artifact.snapshot.files.map(file => file.path));
    for (const fragment of next.fragments) for (const file of fragment.artifact.snapshot.files) {
      if (file.role === 'configuration' && !configurationPaths.has(file.path)) {
        context.artifact.snapshot.files.push({ ...file }); configurationPaths.add(file.path);
      }
    }
    const facts = mergeAnalysisFacts(next.fragments.map(fragment => fragment.artifact), selected);
    context.entities.clear(); facts.entities.forEach(entity => context.entities.set(entity.id, entity));
    facts.relations.forEach(edge => context.relationMap.set(edge.id, edge));
    context.artifact.uncertainties = facts.uncertainties;
    const artifact = context.finish(); context.release();
    deriveAnalysis(artifact, request.metrics, sha);
    this.checkpoint = next; // Publish only after a successful complete assembly.
    return { artifact, execution: { semanticResolution: next.fragments.some(fragment => fragment.semanticResolution) },
      measurements: { elapsedMs: performance.now() - started, peakRssBytes: process.resourceUsage().maxRSS * 1024 },
      update: { changedFiles: current.selected.filter(file => previousFiles.get(file) !== current.local.get(file)),
        removedFiles: [...previousFiles.keys()].filter(file => !selected.has(file)).sort(), analyzedFiles: analyzedFiles.sort(), reusedFiles: reusedFiles.sort(),
        components: next.fragments.length, fallbackReasons: current.fallback, derivedRecomputed: true } };
  }
}
"},{"path":"infrastructure/core/static-analysis/context.ts","text":"import { hash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { readFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import ts from 'typescript';
import { sourceClassification } from '../../../domain/core/static-analysis/classification';
import { sourceLineCount } from '../../../domain/core/static-analysis/sourceText';
import type { StaticAnalysisRequest } from '../../../application/core/static-analysis/ports';
import type { AnalysisArtifact, AnalysisEntity, AnalysisProvenance, AnalysisRange, AnalysisRelation, AnalysisView } from '../../../domain/core/static-analysis/schema';

export const sha = (value: string) => hash('sha256', value, 'hex');
export const ANALYZER_VERSION = '0.4.0';
export const compare = (a: string, b: string) => a < b ? -1 : a > b ? 1 : 0;
export const callable = (node: ts.Node): node is ts.FunctionLikeDeclaration => ts.isFunctionDeclaration(node) || ts.isFunctionExpression(node)
  || ts.isArrowFunction(node) || ts.isMethodDeclaration(node) || ts.isConstructorDeclaration(node) || ts.isGetAccessorDeclaration(node) || ts.isSetAccessorDeclaration(node);
export const views: AnalysisView[] = ['containment', 'lexical', 'calls', 'ownership', 'dependencies'];
let previousProgram: ts.Program | undefined;

export function classify(relative: string): AnalysisEntity['metadata'] {
  const { runtime, owner, composition } = sourceClassification(relative);
  const layer = relative.includes('/__tests__/') || /\.(?:test|integration)\.tsx?$/.test(relative) ? 'test'
    : ({ src: 'ui', domain: 'domain', application: 'application', infrastructure: 'infrastructure', server: 'server', packages: 'package' } as const)[runtime as 'src'] ?? 'other';
  return { layer, feature: owner, compositionRoot: composition };
}

export class AnalysisContext {
  readonly root: string;
  private activeProgram?: ts.Program;
  get program(): ts.Program { if (!this.activeProgram) throw new Error('Analysis compiler context has been released'); return this.activeProgram; }
  private typeChecker?: ts.TypeChecker;
  private semanticReady = false;
  get usedSemanticResolution() { return this.semanticReady; }
  private compilerOptions!: ts.CompilerOptions;
  private compilerRoots!: string[];
  private compilerHost!: ts.CompilerHost;
  get checker() {
    if (!this.semanticReady) {
      const syntax = this.program, host = this.compilerHost;
      const semanticHost = { ...host, getSourceFile: (...args: Parameters<ts.CompilerHost['getSourceFile']>) => syntax.getSourceFile(args[0]) ?? host.getSourceFile(...args) };
      this.activeProgram = ts.createProgram({ rootNames: this.compilerRoots, options: this.compilerOptions, host: semanticHost, oldProgram: previousProgram });
      previousProgram = this.activeProgram; this.semanticReady = true;
    }
    return this.typeChecker ??= this.program.getTypeChecker();
  }
  readonly selected: ts.SourceFile[];
  readonly selectedPaths: Set<string>;
  readonly artifact: AnalysisArtifact;
  readonly entities = new Map<string, AnalysisEntity>();
  readonly nodeEntities = new Map<ts.Node, string>();
  readonly entityNodes = new Map<string, ts.Node>();
  readonly scopes = new Map<ts.Node, string>();
  readonly bindingScopes = new Map<string, string>();
  readonly aliases = new Map<string, string>();
  readonly setters = new Map<string, string>();
  readonly relationMap = new Map<string, AnalysisRelation>();
  readonly callableNodes: ts.FunctionLikeDeclaration[] = [];
  readonly files = new Map<string, { source: ts.SourceFile; hash: string }>();
  private readonly compilerFileHashes = new Map<string, string>();
  private compilerInputsPinned = false;
  readonly duplicates = new Map<string, number>();
  readonly ranges = new Map<ts.Node, AnalysisRange>();
  readonly relativePaths = new Map<string, string>();
  readonly sites = new Map<ts.Node, string>();
  readonly fingerprints = new Map<ts.Node, string>();
  readonly packageDirectories = new Map<string, boolean>();
  readonly syntaxProvenance = new WeakMap<ts.Node, AnalysisProvenance>();
  readonly emptyIds: string[] = [];
  readonly issueIds = new Set<string>();
  readonly siteKeys = new Map<ts.Node, string>();
  readonly siteCounts = new Map<string, number>();
  readonly resourceKinds = new Map<string, NonNullable<AnalysisEntity['metadata']['resourceKind']>>();
  readonly rootId: string;

  constructor(readonly request: StaticAnalysisRequest) {
    this.root = path.resolve(request.repositoryRoot);
    const configPath = path.resolve(this.root, request.tsconfigPath);
    const config = ts.readConfigFile(configPath, ts.sys.readFile);
    if (config.error) throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, '\n'));
    const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, path.dirname(configPath));
    if (parsed.errors.length) throw new Error(parsed.errors.map(error => ts.flattenDiagnosticMessageText(error.messageText, '\n')).join('\n'));
    this.selectedPaths = new Set([...request.includePaths].map(file => this.relative(path.resolve(this.root, file))));
    for (const file of this.selectedPaths) if (file.startsWith('../') || path.isAbsolute(file)) throw new Error('Analysis input escapes repository');
    // Reuse is useful for small interactive slices, but a full run should not keep
    // the previous slice's bound symbols and checker caches alive while rebuilding.
    if (this.selectedPaths.size > 100) previousProgram = undefined;
    const host = ts.createCompilerHost(parsed.options, true);
    // ts.sys.readFile strips a UTF-8 BOM; source evidence must preserve its offset
    // and hash, as well as all original line terminators and surrogate pairs.
    host.readFile = file => { try { return readFileSync(file, 'utf8'); } catch { return undefined; } };
    // TypeScript uses the host directory for implicit @types discovery. A fixture or
    // nested repository must not accidentally inherit this process's checkout types.
    host.getCurrentDirectory = () => this.root;
    const original = host.getSourceFile.bind(host);
    host.getSourceFile = (file, languageVersion, onError, shouldCreateNewSourceFile) => {
      const previous = previousProgram?.getSourceFile(file);
      if (previous && existsSync(file) && readFileSync(file, 'utf8') === previous.text) return previous;
      return original(file, languageVersion, onError, shouldCreateNewSourceFile);
    };
    const roots = [...this.selectedPaths].sort().map(file => path.join(this.root, file));
    roots.push(...parsed.fileNames.filter(file => file.endsWith('.d.ts')));
    this.compilerOptions = parsed.options; this.compilerRoots = [...new Set(roots)]; this.compilerHost = host;
    // Syntax and locally resolved facts do not need to parse/bind the standard library.
    // Build the complete, original project lazily on the first symbol/type query.
    this.activeProgram = ts.createProgram({ rootNames: this.compilerRoots, options: { ...parsed.options, noLib: true, noResolve: true, types: [] }, host });
    this.selected = [...this.selectedPaths].sort().map(file => {
      const source = this.program.getSourceFile(path.join(this.root, file)); if (!source) throw new Error(`Missing source ${file}`); return source;
    });
    if (!this.selected.length) throw new Error('Select at least one source file');
    this.artifact = { schemaVersion: 1,
      snapshot: { id: 'pending', repositoryId: request.repositoryId, commit: null, dirtyFiles: [], files: [],
        analyzer: { version: ANALYZER_VERSION, compilerVersion: ts.version, identityVersion: 1, configurationHash: sha(JSON.stringify({ options: parsed.options, views: request.views, frameworks: request.frameworks, metrics: request.metrics })) },
        tsconfigs: [], scope: { roots: [...this.selectedPaths].sort(), excludedPatterns: ['node_modules/**', 'docs/analysis/artifacts/**'], externalPolicy: 'summarize', followImports: true } },
      entities: [], relations: [], uncertainties: [], layers: [], derived: { sccs: [], trees: [], partitions: [], metrics: [], sourceJoins: [], findings: [] },
      coverage: { analyzedFiles: 0, resolutionOnlyFiles: 0, unresolvedCount: 0, views: views.map(view => ({ view, status: request.views.includes(view) ? 'complete' : 'not-run', candidateSites: 0, resolvedSites: 0, unresolvedSites: 0 })) } };
    for (const source of this.selected) this.trackFile(source);
    const configText = readFileSync(configPath, 'utf8'), relativeConfig = this.relative(configPath);
    this.artifact.snapshot.files.push({ path: relativeConfig, contentHash: sha(configText), utf16Length: configText.length, lineCount: this.lineCount(configText), role: 'configuration', language: 'json' });
    this.artifact.snapshot.tsconfigs.push({ path: relativeConfig, contentHash: sha(configText), effectiveOptionsHash: sha(JSON.stringify(parsed.options)) });
    for (const filename of ['package.json', 'package-lock.json']) {
      const absolute = path.join(this.root, filename);
